    /// <summary>Number of distinct room-state payloads selected by the 262 retail rooms.</summary>
    public const int RetailStateCount = 323;

    /// <summary>Every compiled retail state, including alternate states selected by events and bosses.</summary>
    public static IReadOnlyList<CartridgeRoomState> All { get; } =
        Array.AsReadOnly(definitions);

    static RoomStateDefinitions()
    {
        if (definitions.Length != RetailStateCount)
        {
            throw new InvalidOperationException(
                $"Compiled room-state catalog contains {definitions.Length} records, not {RetailStateCount}.");
        }

        for (int index = 1; index < definitions.Length; index++)
        {
            if (definitions[index - 1].Pointer >= definitions[index].Pointer)
            {
                throw new InvalidOperationException(
                    "Compiled room-state catalog pointers must be unique and sorted.");
            }
        }
    }

    /// <summary>Returns the compiled payload for a selected retail room state.</summary>
    public static CartridgeRoomState Get(ushort statePointer)
    {
        int low = 0;
        int high = definitions.Length - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) >> 1);
            int comparison = definitions[middle].Pointer.CompareTo(statePointer);
            if (comparison == 0)
                return definitions[middle];
            if (comparison < 0)
                low = middle + 1;
            else
                high = middle - 1;
        }

        throw new ArgumentOutOfRangeException(nameof(statePointer), statePointer,
            "Pointer is not one of the 323 selected retail room states.");
    }
}
